sys_variable_value.value:
(function execute(inputs, outputs) {
var ImportExpenseLine = new GlideRecord('u_imp_tmpl_fm_expense_line');
var filter = 'sys_import_set=' + inputs.importSetID;
ImportExpenseLine.addEncodedQuery(filter);
ImportExpenseLine.orderBy('u_cost_plan');
ImportExpenseLine.query();
var filecount = ImportExpenseLine.getRowCount();
outputs.filecount = filecount ;

var uniqueCostPlans = [];

while (ImportExpenseLine.next()) {
    var costPlan = ImportExpenseLine.u_cost_plan.toString();
    if (uniqueCostPlans.indexOf(costPlan) === -1) {
        uniqueCostPlans.push(costPlan);
    }
}


////////////////////////////////////////////

var first = '[code]<br><span style="font-size: 16px;"><b>La demande est annulée à cause des erreur lors de l\'importation du fichier "' +inputs.filename + '"[code]</b></span><br><br>';
var _logInfo = [first];
var notFound = [];
 var affiche = [];
  var affichedup = [];

var taskp = []; 
var duplicatePlans = [];    /////////////////////////////// INC0281011 /////////////////////// 




uniqueCostPlans.forEach(function(name) {
    var gr = new GlideRecord('cost_plan');
    if (!gr.get('name', name)) {
      notFound.push(name);
    }
    if (gr.top_task != gr.task) {
        taskp.push(name);
    }
     // Compter le nombre de plans de coût avec le même nom INC0281011 
        var duplicateGr = new GlideRecord('cost_plan');
        duplicateGr.addQuery('name', name);
        duplicateGr.query();
        if (duplicateGr.getRowCount() > 1) {
            duplicatePlans.push(name);
        }
});

//////////////////////////////////////////////////////////////////////////////////////
function getsumamount(filter) {
    var ImportExpenseLine = new GlideAggregate('u_imp_tmpl_fm_expense_line');
    ImportExpenseLine.addAggregate('sum', 'u_amount');
	gs.log('filter applied:' + filter) ;
    ImportExpenseLine.addEncodedQuery(filter);
    ImportExpenseLine.setGroup(false);
    ImportExpenseLine.query();
    if (ImportExpenseLine.next()) {
		gs.log('sum : ' + ImportExpenseLine.getAggregate('sum', 'u_amount'));
        return ImportExpenseLine.getAggregate('sum', 'u_amount');
    } else {
        gs.log('No records found for aggregation with filter: ' + filter);
    }}
    outputs.expensesum = getsumamount(filter);
    outputs.sum_capex= getsumamount(filter + '^u_expense_type=Capex');
    outputs.sum_opex= getsumamount(filter + '^u_expense_type=Opex');

/////////////////////////////////Le numéro de ligne saisi est différent du numéro de ligne dans votre fichier Excel//////////////////////////////////

if (inputs.fileCountIn != filecount  )  {
 _logInfo.push('[code]<br><b>Le numéro de ligne saisi est différent du numéro de ligne dans le fichier :  </b><br>');
_logInfo.push('- Lignes saisis: ' + inputs.fileCountIn + '[code]<br>');
_logInfo.push('- Lignes dans le fichier: ' + filecount + '[code]<br>');


}
//////////////////////////////////////////La somme des montants des lignes de dépenses dans le fichier Excel est différente////////////////////////////////////
var sumfichier = parseFloat(outputs.expensesum);
var sumInValue = parseFloat(inputs.fileSumIn);
if (sumfichier != sumInValue  )  {
_logInfo.push('[code]<br><b> La somme des montants des lignes de dépenses dans le fichier Excel est différente de celle mentionnée :   </b><br>');
_logInfo.push('- Montants saisis: ' + inputs.fileSumIn + '[code]<br>');
_logInfo.push('- Montants dans le fichier: ' + outputs.expensesum + '[code]<br>');
}

///////////////////////////////////////////////////////////////////Erreur type de dépense//////////////////////////////////////////////////

var gr = new GlideRecord('u_imp_tmpl_fm_expense_line');
gr.orderBy('sys_import_row');
gr.query();

var errorCount = 0;
var errorMessages = [];

while (gr.next()) {
    if (gr.u_expense_type != 'Opex' && gr.u_expense_type != 'Capex') {
errorMessages.push('- Ligne '  + '[code]<b>' + (parseInt(gr.sys_import_row) + 2) +'</b>'+ ' :'+ gr.u_expense_type.toString());        errorCount++;
    }
}

if (errorCount > 0) {
    _logInfo.push('[code]<br><b>La colonne "Expense Type" du ficher contient des erreurs :</b><br>');
    errorMessages.forEach(function(message) {
        _logInfo.push(message + '[code]<br>');
    });
    }

///////////////////////////////////////////////////Les plans de cout qui n existent pas /////////////////////////////////////

if (notFound.length !== 0) {
    _logInfo.push('[code]<b><br>Chacun des plans de coût dans la colonne "Cost plan" doit correspondre à un plan de coût dans ServiceNow. Le(s) plan(s) de coût suivants n\'existent pas :</b><br>');

   var lignes = [];
    notFound.forEach(function(name) {
        var gm = new GlideRecord('u_imp_tmpl_fm_expense_line');
        gm.addQuery('u_cost_plan', name);
        gm.query();

        if (gm.next()) {
            lignes.push({
                name: name,
                row: parseInt(gm.sys_import_row) + 2
            });
        }
    });
    
    lignes.sort(function(a, b) {
        return a.row - b.row;
    });

    lignes.forEach(function(ligne) {
affiche.push(' - Ligne ' + '[code]<b>' + ligne.row + '[code]</b>: ' + ligne.name );    
});
   _logInfo.push(affiche.join('[code]<br>'));
    //_logInfo.push('[code]<br><b> Veuillez vérifier le nom du plan de coût dans le fichier Excel, il doit correspondre à un plan de coût dans ServiceNow. </b><br>');
}



    /////////////////////////////// INC0281011 /////////////////////// 
if (duplicatePlans.length !== 0) {
    _logInfo.push('[code]<b><br>Vous avez des plans de coût avec le même nom:</b><br>');

   var lignesdup = [];
    duplicatePlans.forEach(function(name) {
        var gm = new GlideRecord('u_imp_tmpl_fm_expense_line');
        gm.addQuery('u_cost_plan', name);
        gm.query();

        if (gm.next()) {
            lignesdup.push({
                name: name,
                row: parseInt(gm.sys_import_row) + 2
            });
        }
    });
    lignesdup.sort(function(a, b) {
        return a.row - b.row;
    });

    lignesdup.forEach(function(lignesdup) {
affichedup.push(' - Ligne ' + '[code]<b>' + lignesdup.row + '[code]</b>: ' + lignesdup.name );    
});
   _logInfo.push(affichedup.join('[code]<br>'));
    //_logInfo.push('[code]<br><b> Veuillez vérifier le nom du plan de coût dans le fichier Excel, il doit correspondre à un plan de coût dans ServiceNow. </b><br>');
}


/////////////////////////////// INC0281011 ///////////////////////////////////////


///////////////////////////////////////////****///////////////////// */
/////////////////////////////////**********////////////////////////////////// */
var count = new GlideAggregate('u_imp_tmpl_fm_expense_line');
count.addEncodedQuery('u_cost_planISEMPTY');
count.addAggregate('COUNT');
count.query();
var countamount = 0;
if (count.next())
   countamount = count.getAggregate('COUNT');

   if (countamount > 0 )  {
   //_logInfo.push('[code]<br> il y a des plan du cout qui sont vide\n' + 'Ligne ' + (parseInt(count.sys_import_row) + 2));
   _logInfo.push("[code]<br><b>Le champ 'plan du coût' ne doit pas être vide dans le fichier Excel. Merci.</b>");
    }

    ///////////////////////***************erreur ///////////// */

    var error = new GlideAggregate('u_imp_tmpl_fm_expense_line');
error.addEncodedQuery('u_state!=Pending^ORsys_import_state=error');
error.addAggregate('COUNT');
error.query();
var errorstate = 0;
if (error.next())
   errorstate = error.getAggregate('COUNT');

   if (errorstate > 0 )  {
   //_logInfo.push('[code]<br> il y a des plan du cout qui sont vide\n' + 'Ligne ' + (parseInt(count.sys_import_row) + 2));
   _logInfo.push("[code]<br><b>Il y a une erreur lors de l'importation. Merci de contacter l'administrateur de la plateforme.</b>");
    }




/////////////////////////////////////////////////////Les plans de coût pour lesquels la tâche principale !=  tâche /////////////////////////////////////////////////////

////////////////////// INC0291958 ///////////
/*if (taskp.length !== 0) { 
    _logInfo.push('[code]<br><br><b>Les plans de coûts suivants ont des valeurs différentes dans les 2 champs "Tâche principale" et "Tâche", veuillez les corriger afin d\'éviter la création de doublons dans les lignes de dépenses :</b>' + '[code]<br>');
    taskp = taskp.map(function(name) {
        var gr = new GlideRecord('cost_plan');
        if (gr.get('name', name.trim())) {
            var url = gs.getProperty('glide.servlet.uri') + 'cost_plan.do?sys_id=' + gr.sys_id;
            return '[code]- <a href="' + url + '" target="_blank">' + name + '</a>';
        }
        return '[code]-' + name;
    });

    _logInfo.push(taskp.join('[code]<br>'));
}*/

///////////// fin INC0291958 ////////////////////////////////////////////////
_logInfo.push('[code]<br><br><b>La demande est annulée. Veuillez corriger les erreurs et soumettre une nouvelle demande.</b>' + '[code]<br>');

//////////// INC0291958 ////////
//if (duplicatePlans.length !== 0 || notFound.length !== 0 || taskp.length !== 0 || inputs.fileCountIn != filecount || sumfichier != sumInValue || countamount > 0 || errorstate > 0) {

    ///////// end INC0291958 //////////
    if (duplicatePlans.length !== 0 || notFound.length !== 0 || inputs.fileCountIn != filecount || sumfichier != sumInValue || countamount > 0 || errorstate > 0) {

    outputs.errormsg = _logInfo.join('\n'); 
    outputs.errorstate = true ;
} else {
        outputs.errorstate = false ;
    }

})(inputs, outputs);

